using Neo.L2.State;

namespace Neo.L2.Batch;

/// <summary>
/// Stateful builder that an L2 batcher feeds with blocks, transactions, withdrawals, and
/// cross-chain messages. Once a flush condition is hit, the builder seals the batch and
/// emits an immutable <see cref="SealedBatch"/> via <see cref="SealArtifact"/>.
/// </summary>
/// <remarks>
/// See doc.md §7.2.
/// <para>
/// Flush conditions (size limit, time limit, finality target) are decided externally by the
/// hosting plugin — the builder itself only enforces append-order invariants. Hosts call
/// <see cref="Seal"/> when they decide it is time to settle.
/// </para>
/// </remarks>
public sealed class BatchBuilder
{
    private readonly L2Batch _batch;
    private readonly List<(ulong Nonce, UInt256 TxHash)> _forcedInclusions = new();

    /// <summary>The in-progress batch.</summary>
    public L2Batch Batch => _batch;

    /// <summary>
    /// Forced-inclusion entries staged in this open batch (must precede ordinary txs).
    /// </summary>
    public int ForcedInclusionCount => _forcedInclusions.Count;

    /// <summary>Begin a new batch with the given parameters.</summary>
    public BatchBuilder(uint chainId, ulong batchNumber, ulong firstBlock, UInt256 preStateRoot)
    {
        _batch = new L2Batch(chainId, batchNumber, firstBlock, preStateRoot);
    }

    /// <summary>
    /// Mark a new L2 block as included in the batch (raises <see cref="L2Batch.LastBlock"/>).
    /// The timestamp feeds the execution timeline so transactions of this block execute under its
    /// own index and timestamp.
    /// </summary>
    public BatchBuilder AddBlock(ulong blockIndex, ulong blockTimestamp)
    {
        _batch.AddBlock(blockIndex, blockTimestamp);
        return this;
    }

    /// <summary>Append a serialized transaction.</summary>
    public BatchBuilder AddTransaction(ReadOnlyMemory<byte> serializedTx)
    {
        _batch.AddTransaction(serializedTx);
        return this;
    }

    /// <summary>
    /// Prepend metadata for a forced-inclusion transaction without marking its L1 nonce consumed.
    /// </summary>
    /// <remarks>
    /// <paramref name="txHash"/> must be the canonical transaction id
    /// (<see cref="TransactionHasher.Hash"/>) of <paramref name="serializedTx"/> — the same value
    /// the L1 forced-inclusion queue records and the SP1 guest re-derives. A hash over the full
    /// serialized bytes (witnesses included) does not match and is rejected here.
    /// </remarks>
    public BatchBuilder AddForcedTransaction(
        ulong nonce,
        UInt256 txHash,
        ReadOnlyMemory<byte> serializedTx)
    {
        ArgumentNullException.ThrowIfNull(txHash);
        if (_batch.TransactionCount != _forcedInclusions.Count)
            throw new InvalidOperationException(
                "forced-inclusion transactions must precede ordinary transactions");
        if (_forcedInclusions.Any(entry => entry.Nonce == nonce))
            throw new InvalidOperationException(
                $"forced-inclusion nonce {nonce} is already in this batch");
        var encodedHash = TransactionHasher.Hash(serializedTx);
        if (!encodedHash.Equals(txHash))
            throw new InvalidOperationException(
                $"forced-inclusion nonce {nonce} tx hash does not match encoded transaction");
        _batch.AddTransaction(serializedTx);
        _forcedInclusions.Add((nonce, new UInt256(txHash.GetSpan())));
        return this;
    }

    /// <summary>Mark an inbound L1 message as consumed by this batch.</summary>
    public BatchBuilder ConsumeL1Message(CrossChainMessage message)
    {
        ArgumentNullException.ThrowIfNull(message);
        _batch.AddL1Message(message);
        return this;
    }

    /// <summary>Record a withdrawal that will go into the batch's withdrawal Merkle tree.</summary>
    public BatchBuilder AddWithdrawal(WithdrawalRequest withdrawal)
    {
        ArgumentNullException.ThrowIfNull(withdrawal);
        _batch.AddWithdrawal(withdrawal);
        return this;
    }

    /// <summary>Record an L2 → L1 message emitted during execution.</summary>
    public BatchBuilder AddL2ToL1Message(CrossChainMessage message)
    {
        ArgumentNullException.ThrowIfNull(message);
        _batch.AddL2ToL1Message(message);
        return this;
    }

    /// <summary>Record an L2 → L2 message emitted during execution.</summary>
    public BatchBuilder AddL2ToL2Message(CrossChainMessage message)
    {
        ArgumentNullException.ThrowIfNull(message);
        _batch.AddL2ToL2Message(message);
        return this;
    }

    /// <summary>Set the deterministic block context that will be hashed into the public inputs.</summary>
    public BatchBuilder WithBlockContext(BatchBlockContext context)
    {
        _batch.BlockContext = context;
        return this;
    }

    /// <summary>
    /// Produce a <see cref="BatchExecutionRequest"/> ready to feed to <see cref="IL2BatchExecutor"/>.
    /// Caller is expected to invoke the executor and pair the result with this request to produce
    /// the final <see cref="L2BatchCommitment"/> via <see cref="ToCommitment"/>.
    /// </summary>
    public BatchExecutionRequest ToExecutionRequest()
    {
        var ctx = _batch.BlockContext ?? throw new InvalidOperationException("BlockContext must be set before sealing");
        return new BatchExecutionRequest
        {
            ChainId = _batch.ChainId,
            BatchNumber = _batch.BatchNumber,
            PreStateRoot = _batch.PreStateRoot,
            Transactions = _batch.Transactions,
            L1MessagesConsumed = _batch.L1MessagesConsumed,
            BlockTimeline = _batch.BlockTimeline,
            BlockContext = ctx,
        };
    }

    /// <summary>
    /// Seal the exact executable inputs without inventing execution roots, a DA commitment,
    /// public-input hash, or proof. The sealed artifact also carries the staged message side
    /// (withdrawals, L2 → L1, L2 → L2 messages) so a receiver can reconstruct every root the
    /// batch commits to.
    /// </summary>
    /// <remarks>
    /// The forced-inclusion consumption tree is only built when the batch actually carries forced
    /// inclusions, and its leaves are canonical transaction ids
    /// (<see cref="TransactionHasher.Hash"/>): the consumption proof must fold to the commitment's
    /// txRoot, which the SP1 guest computes over canonical ids.
    /// </remarks>
    public SealedBatch SealArtifact()
    {
        var context = _batch.BlockContext
            ?? throw new InvalidOperationException("BlockContext must be set before sealing");
        var forcedProofs = Array.Empty<ForcedInclusionConsumptionProof>();
        if (_forcedInclusions.Count > 0)
        {
            var transactionHashes = _batch.Transactions
                .Select(TransactionHasher.Hash)
                .ToArray();
            var transactionTree = new Neo.L2.State.MerkleTree(transactionHashes);
            forcedProofs = new ForcedInclusionConsumptionProof[_forcedInclusions.Count];
            for (var index = 0; index < forcedProofs.Length; index++)
            {
                var entry = _forcedInclusions[index];
                var proof = transactionTree.GetProof(index);
                forcedProofs[index] = new ForcedInclusionConsumptionProof
                {
                    Nonce = entry.Nonce,
                    LeafIndex = checked((uint)index),
                    TxHash = entry.TxHash,
                    Siblings = proof.Siblings,
                };
            }
        }
        _batch.Seal();
        return new SealedBatch(
            _batch.ChainId,
            _batch.BatchNumber,
            _batch.FirstBlock,
            _batch.LastBlock,
            _batch.PreStateRoot,
            _batch.Transactions,
            _batch.L1MessagesConsumed,
            context,
            forcedProofs,
            _batch.BlockTimeline,
            _batch.Withdrawals,
            _batch.L2ToL1Messages,
            _batch.L2ToL2Messages);
    }

    /// <summary>
    /// Combine an executor result with this builder's metadata to produce the final
    /// <see cref="L2BatchCommitment"/>. Seals the underlying batch.
    /// </summary>
    public L2BatchCommitment ToCommitment(
        BatchExecutionResult executionResult,
        UInt256 daCommitment,
        UInt256 publicInputHash,
        ProofType proofType,
        ReadOnlyMemory<byte> proof)
    {
        ArgumentNullException.ThrowIfNull(executionResult);
        // Defense-in-depth: daCommitment and publicInputHash are UInt256 (reference type),
        // and `_batch.Seal()` below mutates state irreversibly. If a null hash slips through
        // here, the iter-156/157 BatchSerializer.Encode null-guards would catch it later
        // — but only AFTER the batch is sealed. Surface it here so a re-attempt can succeed.
        ArgumentNullException.ThrowIfNull(daCommitment);
        ArgumentNullException.ThrowIfNull(publicInputHash);
        _batch.Seal();
        return new L2BatchCommitment
        {
            ChainId = _batch.ChainId,
            BatchNumber = _batch.BatchNumber,
            FirstBlock = _batch.FirstBlock,
            LastBlock = _batch.LastBlock,
            PreStateRoot = _batch.PreStateRoot,
            PostStateRoot = executionResult.PostStateRoot,
            TxRoot = executionResult.TxRoot,
            ReceiptRoot = executionResult.ReceiptRoot,
            WithdrawalRoot = executionResult.WithdrawalRoot,
            L2ToL1MessageRoot = executionResult.L2ToL1MessageRoot,
            L2ToL2MessageRoot = executionResult.L2ToL2MessageRoot,
            DACommitment = daCommitment,
            PublicInputHash = publicInputHash,
            ProofType = proofType,
            Proof = proof,
        };
    }

    /// <summary>Convenience: seal and return commitment in one call.</summary>
    public L2BatchCommitment Seal(
        BatchExecutionResult executionResult,
        UInt256 daCommitment,
        UInt256 publicInputHash,
        ProofType proofType,
        ReadOnlyMemory<byte> proof) =>
        ToCommitment(executionResult, daCommitment, publicInputHash, proofType, proof);
}

using System.Buffers.Binary;

namespace Neo.L2.Batch;

/// <summary>
/// Canonical, deterministic encoding for <see cref="L2BatchCommitment"/> and <see cref="PublicInputs"/>.
/// </summary>
/// <remarks>
/// All multi-byte integers are little-endian (matches Neo on-chain conventions). UInt160 / UInt256
/// are encoded as their 20- / 32-byte payloads. Proof bytes are length-prefixed (32-bit LE length).
/// <para>
/// The two layouts bind different boundaries, and only one of them is an L1 ABI. The commitment
/// header is the byte format <c>SettlementManager.submitBatch</c> parses, so any change to it is a
/// breaking on-chain change. The 352-byte public-inputs form is <em>never</em> transmitted to L1 —
/// the contract sees only its 32-byte digest, at commitment offset 284 — but it is still the exact
/// preimage the committee/sequencer signature is taken over
/// (<c>src/Neo.L2.Proving/Attestation/AttestationProver.cs:36-40</c>,
/// <c>src/Neo.L2.Proving/Optimistic/OptimisticProver.cs:81-83</c>), the digest recorded in every
/// durable witness artifact (<c>src/Neo.L2.Persistence/ProofWitnessStore.cs:1090-1091</c>), the
/// equality check that gates execution
/// (<c>src/Neo.L2.Executor/Witness/Sp1StatefulBatchExecutor.cs:271-272</c>), and the buffer the Rust
/// side rebuilds byte-for-byte (<c>bridge/neo-execution-core/src/hashing.rs</c>) <em>and</em> the
/// contract rebuilds from the header plus its two extra arguments — since the digest binds
/// <c>firstBlock</c>/<c>lastBlock</c>, a change to it is a breaking on-chain change too.
/// </para>
/// <para>
/// <b>L2BatchCommitment layout (321 + proofLen bytes):</b>
/// <code>
/// offset  size       field
/// 0       4          chainId (uint32)
/// 4       8          batchNumber (uint64)
/// 12      8          firstBlock (uint64)
/// 20      8          lastBlock (uint64)
/// 28      32         preStateRoot
/// 60      32         postStateRoot
/// 92      32         txRoot
/// 124     32         receiptRoot
/// 156     32         withdrawalRoot
/// 188     32         l2ToL1MessageRoot
/// 220     32         l2ToL2MessageRoot
/// 252     32         daCommitment
/// 284     32         publicInputHash
/// 316     1          proofType (byte)
/// 317     4          proofLen (int32)
/// 321     proofLen   proof bytes
/// </code>
/// </para>
/// <para>
/// <b>PublicInputs layout (352 bytes, fixed):</b>
/// <code>
/// offset  size  field
/// 0       4     chainId (uint32)
/// 4       8     batchNumber (uint64)
/// 12      8     firstBlock (uint64)
/// 20      8     lastBlock (uint64)
/// 28      32    preStateRoot
/// 60      32    postStateRoot
/// 92      32    txRoot
/// 124     32    receiptRoot
/// 156     32    withdrawalRoot
/// 188     32    l2ToL1MessageRoot
/// 220     32    l2ToL2MessageRoot
/// 252     32    l1MessageHash
/// 284     32    daCommitment
/// 316     32    blockContextHash
/// 348     4     forcedInclusionCount (uint32)
/// </code>
/// </para>
/// </remarks>
public static class BatchSerializer
{
    private const int ProofMaxBytes = 1 * 1024 * 1024; // 1 MiB cap matches NeoHub's defensive limit.

    /// <summary>Fixed-size portion of an <see cref="L2BatchCommitment"/> encoding.
    /// Includes the 4-byte proof length prefix (the proof bytes themselves are varbytes).
    /// Total = 4 + 8 + 8 + 8 + 9×32 + 1 + 4 = 321 bytes.</summary>
    public const int CommitmentFixedSize =
        4 +              // ChainId
        8 + 8 + 8 +      // BatchNumber, FirstBlock, LastBlock
        9 * 32 +         // 9× UInt256 roots/hashes
        1 +              // ProofType
        4;               // proof length prefix

    /// <summary>Total size of <see cref="PublicInputs"/> encoding (no varbytes).</summary>
    public const int PublicInputsSize =
        4 +              // ChainId
        8 + 8 + 8 +      // BatchNumber, FirstBlock, LastBlock
        10 * 32 +        // 10× UInt256 roots/hashes
        4;               // ForcedInclusionCount

    /// <summary>Encode <paramref name="commitment"/> to its canonical byte form.</summary>
    public static byte[] Encode(L2BatchCommitment commitment)
    {
        ArgumentNullException.ThrowIfNull(commitment);
        // Defense-in-depth: all 9 root fields are UInt256 (reference type) — null in
        // any one would crash inside WriteUInt256's GetSpan(). Same iter-154/155/156
        // hashing-primitive null-guard pattern.
        ArgumentNullException.ThrowIfNull(commitment.PreStateRoot);
        ArgumentNullException.ThrowIfNull(commitment.PostStateRoot);
        ArgumentNullException.ThrowIfNull(commitment.TxRoot);
        ArgumentNullException.ThrowIfNull(commitment.ReceiptRoot);
        ArgumentNullException.ThrowIfNull(commitment.WithdrawalRoot);
        ArgumentNullException.ThrowIfNull(commitment.L2ToL1MessageRoot);
        ArgumentNullException.ThrowIfNull(commitment.L2ToL2MessageRoot);
        ArgumentNullException.ThrowIfNull(commitment.DACommitment);
        ArgumentNullException.ThrowIfNull(commitment.PublicInputHash);
        if (commitment.Proof.Length > ProofMaxBytes)
            throw new ArgumentException($"Proof bytes exceed maximum {ProofMaxBytes}", nameof(commitment));
        // Encode/Decode symmetry: Decode rejects ProofType bytes > Zk (iter 103). Refuse
        // to Encode bytes the round-trip would later fail on. Same iter-159 pattern as
        // OptimisticProofPayload / RiscVProofPayload size-cap symmetry.
        if (commitment.ProofType > ProofType.Zk)
            throw new ArgumentException(
                $"ProofType {(byte)commitment.ProofType} not in defined range [0..{(byte)ProofType.Zk}]",
                nameof(commitment));

        // checked: a Proof.Length near int.MaxValue (caught later by ProofMaxBytes, but
        // not here at allocation time) wraps. Surface as OverflowException at the sum
        // site so the cause is visible.
        var bufferSize = checked(CommitmentFixedSize + commitment.Proof.Length);
        var buffer = new byte[bufferSize];
        var span = buffer.AsSpan();
        var pos = 0;

        BinaryPrimitives.WriteUInt32LittleEndian(span.Slice(pos, 4), commitment.ChainId); pos += 4;
        BinaryPrimitives.WriteUInt64LittleEndian(span.Slice(pos, 8), commitment.BatchNumber); pos += 8;
        BinaryPrimitives.WriteUInt64LittleEndian(span.Slice(pos, 8), commitment.FirstBlock); pos += 8;
        BinaryPrimitives.WriteUInt64LittleEndian(span.Slice(pos, 8), commitment.LastBlock); pos += 8;

        WriteUInt256(span, ref pos, commitment.PreStateRoot);
        WriteUInt256(span, ref pos, commitment.PostStateRoot);
        WriteUInt256(span, ref pos, commitment.TxRoot);
        WriteUInt256(span, ref pos, commitment.ReceiptRoot);
        WriteUInt256(span, ref pos, commitment.WithdrawalRoot);
        WriteUInt256(span, ref pos, commitment.L2ToL1MessageRoot);
        WriteUInt256(span, ref pos, commitment.L2ToL2MessageRoot);
        WriteUInt256(span, ref pos, commitment.DACommitment);
        WriteUInt256(span, ref pos, commitment.PublicInputHash);

        span[pos++] = (byte)commitment.ProofType;
        BinaryPrimitives.WriteInt32LittleEndian(span.Slice(pos, 4), commitment.Proof.Length); pos += 4;

        commitment.Proof.Span.CopyTo(span.Slice(pos));
        pos += commitment.Proof.Length;

        if (pos != buffer.Length)
            throw new InvalidOperationException($"BatchSerializer.Encode internal length mismatch: pos={pos}, buf={buffer.Length}");

        return buffer;
    }

    /// <summary>Decode a canonical byte form back to <see cref="L2BatchCommitment"/>.</summary>
    public static L2BatchCommitment Decode(ReadOnlySpan<byte> data)
    {
        if (data.Length < CommitmentFixedSize)
            throw new ArgumentException($"Buffer too small: {data.Length} < {CommitmentFixedSize}", nameof(data));

        var pos = 0;
        var chainId = BinaryPrimitives.ReadUInt32LittleEndian(data.Slice(pos, 4)); pos += 4;
        var batchNumber = BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(pos, 8)); pos += 8;
        var firstBlock = BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(pos, 8)); pos += 8;
        var lastBlock = BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(pos, 8)); pos += 8;

        if (lastBlock < firstBlock)
            throw new InvalidDataException($"lastBlock ({lastBlock}) < firstBlock ({firstBlock}) in decoded commitment");

        var preStateRoot = ReadUInt256(data, ref pos);
        var postStateRoot = ReadUInt256(data, ref pos);
        var txRoot = ReadUInt256(data, ref pos);
        var receiptRoot = ReadUInt256(data, ref pos);
        var withdrawalRoot = ReadUInt256(data, ref pos);
        var l2ToL1MessageRoot = ReadUInt256(data, ref pos);
        var l2ToL2MessageRoot = ReadUInt256(data, ref pos);
        var daCommitment = ReadUInt256(data, ref pos);
        var publicInputHash = ReadUInt256(data, ref pos);

        // Validate ProofType byte is within the defined enum range. An untrusted decoder
        // input (corrupted L1 calldata, replayed older batch from a different version)
        // could carry an unknown discriminant — without this check it would propagate as
        // an undefined ProofType, and downstream `==` comparisons would silently treat it
        // as "not the expected one" rather than rejecting the batch outright.
        var proofTypeByte = data[pos++];
        if (proofTypeByte > (byte)ProofType.Zk)
            throw new InvalidDataException($"Unknown ProofType byte {proofTypeByte} (max {(byte)ProofType.Zk})");
        var proofType = (ProofType)proofTypeByte;

        var proofLen = BinaryPrimitives.ReadInt32LittleEndian(data.Slice(pos, 4)); pos += 4;

        if (proofLen < 0 || proofLen > ProofMaxBytes)
            throw new InvalidDataException($"Invalid proof length {proofLen}");
        // Strict length match: trailing bytes after the proof would be silently ignored,
        // creating a malleability surface where the same logical commitment yields
        // different on-chain hashes if the L1 contract hashes the full calldata while
        // the L2 decoder strips trailing bytes. Same defensive pattern as
        // OptimisticProofPayload.Decode and DepositPayload.Decode.
        if (pos + proofLen != data.Length)
            throw new InvalidDataException(
                $"Buffer length mismatch: expected {pos + proofLen}, have {data.Length}");

        var proof = data.Slice(pos, proofLen).ToArray();

        return new L2BatchCommitment
        {
            ChainId = chainId,
            BatchNumber = batchNumber,
            FirstBlock = firstBlock,
            LastBlock = lastBlock,
            PreStateRoot = preStateRoot,
            PostStateRoot = postStateRoot,
            TxRoot = txRoot,
            ReceiptRoot = receiptRoot,
            WithdrawalRoot = withdrawalRoot,
            L2ToL1MessageRoot = l2ToL1MessageRoot,
            L2ToL2MessageRoot = l2ToL2MessageRoot,
            DACommitment = daCommitment,
            PublicInputHash = publicInputHash,
            ProofType = proofType,
            Proof = proof,
        };
    }

    /// <summary>Encode <paramref name="inputs"/> to its canonical byte form.</summary>
    public static byte[] EncodePublicInputs(PublicInputs inputs)
    {
        ArgumentNullException.ThrowIfNull(inputs);
        // Defense-in-depth: 10 UInt256 fields, mirror StateRootCalculator.HashPublicInputs.
        ArgumentNullException.ThrowIfNull(inputs.PreStateRoot);
        ArgumentNullException.ThrowIfNull(inputs.PostStateRoot);
        ArgumentNullException.ThrowIfNull(inputs.TxRoot);
        ArgumentNullException.ThrowIfNull(inputs.ReceiptRoot);
        ArgumentNullException.ThrowIfNull(inputs.WithdrawalRoot);
        ArgumentNullException.ThrowIfNull(inputs.L2ToL1MessageRoot);
        ArgumentNullException.ThrowIfNull(inputs.L2ToL2MessageRoot);
        ArgumentNullException.ThrowIfNull(inputs.L1MessageHash);
        ArgumentNullException.ThrowIfNull(inputs.DACommitment);
        ArgumentNullException.ThrowIfNull(inputs.BlockContextHash);
        var buffer = new byte[PublicInputsSize];
        var span = buffer.AsSpan();
        var pos = 0;

        BinaryPrimitives.WriteUInt32LittleEndian(span.Slice(pos, 4), inputs.ChainId); pos += 4;
        BinaryPrimitives.WriteUInt64LittleEndian(span.Slice(pos, 8), inputs.BatchNumber); pos += 8;
        BinaryPrimitives.WriteUInt64LittleEndian(span.Slice(pos, 8), inputs.FirstBlock); pos += 8;
        BinaryPrimitives.WriteUInt64LittleEndian(span.Slice(pos, 8), inputs.LastBlock); pos += 8;

        WriteUInt256(span, ref pos, inputs.PreStateRoot);
        WriteUInt256(span, ref pos, inputs.PostStateRoot);
        WriteUInt256(span, ref pos, inputs.TxRoot);
        WriteUInt256(span, ref pos, inputs.ReceiptRoot);
        WriteUInt256(span, ref pos, inputs.WithdrawalRoot);
        WriteUInt256(span, ref pos, inputs.L2ToL1MessageRoot);
        WriteUInt256(span, ref pos, inputs.L2ToL2MessageRoot);
        WriteUInt256(span, ref pos, inputs.L1MessageHash);
        WriteUInt256(span, ref pos, inputs.DACommitment);
        WriteUInt256(span, ref pos, inputs.BlockContextHash);
        BinaryPrimitives.WriteUInt32LittleEndian(span.Slice(pos, 4), inputs.ForcedInclusionCount); pos += 4;

        if (pos != buffer.Length)
            throw new InvalidOperationException($"EncodePublicInputs internal length mismatch: pos={pos}, buf={buffer.Length}");

        return buffer;
    }

    /// <summary>Decode a canonical <see cref="PublicInputs"/> byte form.</summary>
    public static PublicInputs DecodePublicInputs(ReadOnlySpan<byte> data)
    {
        if (data.Length != PublicInputsSize)
            throw new ArgumentException($"Buffer size {data.Length} != expected {PublicInputsSize}", nameof(data));

        var pos = 0;
        var chainId = BinaryPrimitives.ReadUInt32LittleEndian(data.Slice(pos, 4)); pos += 4;
        var batchNumber = BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(pos, 8)); pos += 8;
        var firstBlock = BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(pos, 8)); pos += 8;
        var lastBlock = BinaryPrimitives.ReadUInt64LittleEndian(data.Slice(pos, 8)); pos += 8;
        if (lastBlock < firstBlock)
            throw new InvalidDataException($"lastBlock ({lastBlock}) < firstBlock ({firstBlock}) in decoded public inputs");

        var preStateRoot = ReadUInt256(data, ref pos);
        var postStateRoot = ReadUInt256(data, ref pos);
        var txRoot = ReadUInt256(data, ref pos);
        var receiptRoot = ReadUInt256(data, ref pos);
        var withdrawalRoot = ReadUInt256(data, ref pos);
        var l2ToL1MessageRoot = ReadUInt256(data, ref pos);
        var l2ToL2MessageRoot = ReadUInt256(data, ref pos);
        var l1MessageHash = ReadUInt256(data, ref pos);
        var daCommitment = ReadUInt256(data, ref pos);
        var blockContextHash = ReadUInt256(data, ref pos);
        var forcedInclusionCount = BinaryPrimitives.ReadUInt32LittleEndian(data.Slice(pos, 4)); pos += 4;

        return new PublicInputs
        {
            ChainId = chainId,
            BatchNumber = batchNumber,
            FirstBlock = firstBlock,
            LastBlock = lastBlock,
            PreStateRoot = preStateRoot,
            PostStateRoot = postStateRoot,
            TxRoot = txRoot,
            ReceiptRoot = receiptRoot,
            WithdrawalRoot = withdrawalRoot,
            L2ToL1MessageRoot = l2ToL1MessageRoot,
            L2ToL2MessageRoot = l2ToL2MessageRoot,
            L1MessageHash = l1MessageHash,
            DACommitment = daCommitment,
            BlockContextHash = blockContextHash,
            ForcedInclusionCount = forcedInclusionCount,
        };
    }

    private static void WriteUInt256(Span<byte> span, ref int pos, UInt256 value)
    {
        value.GetSpan().CopyTo(span.Slice(pos, 32));
        pos += 32;
    }

    private static UInt256 ReadUInt256(ReadOnlySpan<byte> span, ref int pos)
    {
        var slice = span.Slice(pos, 32);
        pos += 32;
        return new UInt256(slice);
    }
}

