using Neo.L2.State;

namespace Neo.L2.Batch;

/// <summary>
/// Immutable executable batch produced before execution, DA publication, proving, or settlement.
/// </summary>
/// <remarks>
/// See doc.md §7.2, §8.1, and §15.1. All variable byte fields are deep-copied so the
/// execution payload cannot change after sealing.
/// </remarks>
public sealed class SealedBatch
{
    private readonly IReadOnlyList<ReadOnlyMemory<byte>> _transactions;
    private readonly IReadOnlyList<CrossChainMessage> _l1Messages;
    private readonly IReadOnlyList<ForcedInclusionConsumptionProof> _forcedInclusions;
    private readonly IReadOnlyList<L2BatchBlock>? _blockTimeline;
    private readonly IReadOnlyList<WithdrawalRequest>? _withdrawals;
    private readonly IReadOnlyList<CrossChainMessage>? _l2ToL1Messages;
    private readonly IReadOnlyList<CrossChainMessage>? _l2ToL2Messages;

    /// <summary>L2 chain identifier.</summary>
    public uint ChainId { get; }

    /// <summary>Monotonic batch number.</summary>
    public ulong BatchNumber { get; }

    /// <summary>Inclusive first L2 block.</summary>
    public ulong FirstBlock { get; }

    /// <summary>Inclusive last L2 block.</summary>
    public ulong LastBlock { get; }

    /// <summary>Canonical state root before execution.</summary>
    public UInt256 PreStateRoot { get; }

    /// <summary>Ordered canonical transaction bytes.</summary>
    public IReadOnlyList<ReadOnlyMemory<byte>> Transactions => _transactions;

    /// <summary>Ordered L1 inbox messages consumed before transactions.</summary>
    public IReadOnlyList<CrossChainMessage> L1Messages => _l1Messages;

    /// <summary>Forced-inclusion transaction positions and Merkle proof material.</summary>
    public IReadOnlyList<ForcedInclusionConsumptionProof> ForcedInclusions => _forcedInclusions;

    /// <summary>Forced-inclusion nonces durably tracked from sealing through L1 consumption.</summary>
    public IReadOnlyList<ulong> ForcedInclusionNonces =>
        _forcedInclusions.Select(static proof => proof.Nonce).ToArray();

    /// <summary>Deterministic block context consumed by execution.</summary>
    public BatchBlockContext BlockContext { get; }

    /// <summary>
    /// Withdrawals the batcher staged for the withdrawal Merkle tree; the leaf material behind
    /// <c>WithdrawalRoot</c>. <c>null</c> only for instances reconstructed from decoded payloads,
    /// which carry no message side.
    /// </summary>
    public IReadOnlyList<WithdrawalRequest>? Withdrawals => _withdrawals;

    /// <summary>
    /// L2 → L1 messages the batcher staged; the leaf material behind <c>L2ToL1MessageRoot</c>.
    /// <c>null</c> only for instances reconstructed from decoded payloads, which carry no
    /// message side.
    /// </summary>
    public IReadOnlyList<CrossChainMessage>? L2ToL1Messages => _l2ToL1Messages;

    /// <summary>
    /// L2 → L2 messages the batcher staged; the leaf material behind <c>L2ToL2MessageRoot</c>.
    /// <c>null</c> only for instances reconstructed from decoded payloads, which carry no
    /// message side.
    /// </summary>
    public IReadOnlyList<CrossChainMessage>? L2ToL2Messages => _l2ToL2Messages;

    /// <summary>
    /// Per-block execution timeline, when this batch was sealed by a batcher that attributed its
    /// transactions to blocks. <c>null</c> only for instances reconstructed from decoded payloads,
    /// which cannot re-derive block attribution; <see cref="ToExecutionRequest"/> refuses those.
    /// </summary>
    public IReadOnlyList<L2BatchBlock>? BlockTimeline => _blockTimeline;

    /// <summary>Create an immutable sealed batch.</summary>
    public SealedBatch(
        uint chainId,
        ulong batchNumber,
        ulong firstBlock,
        ulong lastBlock,
        UInt256 preStateRoot,
        IReadOnlyList<ReadOnlyMemory<byte>> transactions,
        IReadOnlyList<CrossChainMessage> l1Messages,
        BatchBlockContext blockContext,
        IReadOnlyList<ForcedInclusionConsumptionProof>? forcedInclusions = null,
        IReadOnlyList<L2BatchBlock>? blockTimeline = null,
        IReadOnlyList<WithdrawalRequest>? withdrawals = null,
        IReadOnlyList<CrossChainMessage>? l2ToL1Messages = null,
        IReadOnlyList<CrossChainMessage>? l2ToL2Messages = null)
    {
        ArgumentNullException.ThrowIfNull(preStateRoot);
        ArgumentNullException.ThrowIfNull(transactions);
        ArgumentNullException.ThrowIfNull(l1Messages);
        ArgumentNullException.ThrowIfNull(blockContext);
        ArgumentNullException.ThrowIfNull(blockContext.SequencerCommitteeHash);
        if (lastBlock < firstBlock)
            throw new ArgumentOutOfRangeException(
                nameof(lastBlock), "lastBlock must not precede firstBlock");
        if (blockTimeline is not null)
            BlockTimelineValidator.Validate(
                blockTimeline, transactions.Count, firstBlock, lastBlock, blockContext);

        ChainId = chainId;
        BatchNumber = batchNumber;
        FirstBlock = firstBlock;
        LastBlock = lastBlock;
        PreStateRoot = new UInt256(preStateRoot.GetSpan());
        BlockContext = blockContext with
        {
            SequencerCommitteeHash = new UInt256(
                blockContext.SequencerCommitteeHash.GetSpan()),
        };
        _blockTimeline = blockTimeline is null
            ? null
            : Array.AsReadOnly(blockTimeline.Select(static entry => entry!).ToArray());

        var transactionCopies = new ReadOnlyMemory<byte>[transactions.Count];
        for (var index = 0; index < transactions.Count; index++)
            transactionCopies[index] = transactions[index].ToArray();
        _transactions = Array.AsReadOnly(transactionCopies);

        var forcedSource = forcedInclusions
            ?? Array.Empty<ForcedInclusionConsumptionProof>();
        var forcedCopies = new ForcedInclusionConsumptionProof[forcedSource.Count];
        if (forcedCopies.Length > transactionCopies.Length)
            throw new ArgumentException(
                "forced-inclusion nonce count exceeds transaction count",
                nameof(forcedInclusions));
        // Leaf identity is the canonical transaction id (TransactionHasher): the same value the
        // SP1 guest folds into the commitment txRoot, so a consumption proof that survives this
        // validation also folds to the finalized root on L1. Full-serialized-bytes hashes belong
        // to no consumer of this tree.
        var transactionHashes = forcedCopies.Length > 0
            ? transactionCopies
                .Select(TransactionHasher.Hash)
                .ToArray()
            : Array.Empty<UInt256>();
        var transactionTree = forcedCopies.Length > 0
            ? new Neo.L2.State.MerkleTree(transactionHashes)
            : null;
        var nonces = new HashSet<ulong>();
        for (var index = 0; index < forcedSource.Count; index++)
        {
            var proof = forcedSource[index]
                ?? throw new ArgumentException(
                    $"forcedInclusions[{index}] is null", nameof(forcedInclusions));
            ArgumentNullException.ThrowIfNull(proof.TxHash);
            ArgumentNullException.ThrowIfNull(proof.Siblings);
            if (proof.LeafIndex != (uint)index)
                throw new ArgumentException(
                    "forced-inclusion transactions must occupy the leading transaction positions",
                    nameof(forcedInclusions));
            if (!nonces.Add(proof.Nonce))
                throw new ArgumentException(
                    "forced-inclusion nonces must be unique within a batch",
                    nameof(forcedInclusions));
            if (!proof.TxHash.Equals(transactionHashes[index]))
                throw new ArgumentException(
                    $"forced-inclusion tx hash {index} does not match encoded transaction",
                    nameof(forcedInclusions));
            var canonicalProof = transactionTree!.GetProof(index);
            if (!canonicalProof.Siblings.SequenceEqual(proof.Siblings))
                throw new ArgumentException(
                    $"forced-inclusion proof {index} is not canonical for the batch transaction root",
                    nameof(forcedInclusions));
            forcedCopies[index] = proof with
            {
                TxHash = new UInt256(proof.TxHash.GetSpan()),
                Siblings = Array.AsReadOnly(proof.Siblings
                    .Select(static sibling => new UInt256(sibling.GetSpan()))
                    .ToArray()),
            };
        }
        if (forcedCopies.Length != nonces.Count)
            throw new ArgumentException(
                "forced-inclusion nonces must be unique within a batch",
                nameof(forcedInclusions));
        _forcedInclusions = Array.AsReadOnly(forcedCopies);

        _l1Messages = CopyMessages(l1Messages, nameof(l1Messages))!;
        _withdrawals = CopyWithdrawals(withdrawals);
        _l2ToL1Messages = CopyMessages(l2ToL1Messages, nameof(l2ToL1Messages));
        _l2ToL2Messages = CopyMessages(l2ToL2Messages, nameof(l2ToL2Messages));
    }

    private static IReadOnlyList<CrossChainMessage>? CopyMessages(
        IReadOnlyList<CrossChainMessage>? messages, string paramName)
    {
        if (messages is null)
            return null;
        var messageCopies = new CrossChainMessage[messages.Count];
        for (var index = 0; index < messages.Count; index++)
        {
            var message = messages[index]
                ?? throw new ArgumentException(
                    $"{paramName}[{index}] is null", paramName);
            ArgumentNullException.ThrowIfNull(message.Sender);
            ArgumentNullException.ThrowIfNull(message.Receiver);
            ArgumentNullException.ThrowIfNull(message.MessageHash);
            messageCopies[index] = message with
            {
                Sender = new UInt160(message.Sender.GetSpan()),
                Receiver = new UInt160(message.Receiver.GetSpan()),
                Payload = message.Payload.ToArray(),
                MessageHash = new UInt256(message.MessageHash.GetSpan()),
            };
        }
        return Array.AsReadOnly(messageCopies);
    }

    private static IReadOnlyList<WithdrawalRequest>? CopyWithdrawals(
        IReadOnlyList<WithdrawalRequest>? withdrawals)
    {
        if (withdrawals is null)
            return null;
        var withdrawalCopies = new WithdrawalRequest[withdrawals.Count];
        for (var index = 0; index < withdrawals.Count; index++)
        {
            var withdrawal = withdrawals[index]
                ?? throw new ArgumentException(
                    $"withdrawals[{index}] is null", nameof(withdrawals));
            withdrawalCopies[index] = withdrawal with
            {
                EmittingContract = new UInt160(withdrawal.EmittingContract.GetSpan()),
                L2Sender = new UInt160(withdrawal.L2Sender.GetSpan()),
                L1Recipient = new UInt160(withdrawal.L1Recipient.GetSpan()),
                L2Asset = new UInt160(withdrawal.L2Asset.GetSpan()),
            };
        }
        return Array.AsReadOnly(withdrawalCopies);
    }

    /// <summary>Build the exact executor request represented by this sealed batch.</summary>
    public BatchExecutionRequest ToExecutionRequest()
    {
        // Fail closed: a batch with transactions but no per-block attribution has no honest
        // execution header, and silently falling back to batch-level header values is the
        // defect this seam exists to remove. Payload-decoded instances carry no timeline.
        if (_blockTimeline is null && _transactions.Count > 0)
            throw new InvalidOperationException(
                "sealed batch carries transactions but no block timeline; execution requires per-block attribution");
        return new BatchExecutionRequest
        {
            ChainId = ChainId,
            BatchNumber = BatchNumber,
            PreStateRoot = PreStateRoot,
            Transactions = Transactions,
            L1MessagesConsumed = L1Messages,
            BlockTimeline = _blockTimeline ?? Array.Empty<L2BatchBlock>(),
            BlockContext = BlockContext,
        };
    }

    /// <summary>Build the exact versioned payload published to DA.</summary>
    public ExecutionPayloadV1 ToExecutionPayload() => new()
    {
        ChainId = ChainId,
        BatchNumber = BatchNumber,
        FirstBlock = FirstBlock,
        LastBlock = LastBlock,
        PreStateRoot = PreStateRoot,
        BlockContext = BlockContext,
        L1Messages = L1Messages,
        ForcedInclusions = ForcedInclusions,
        Transactions = Transactions,
    };
}

/// <summary>Latest continuously persisted batch hand-off acknowledged by execution.</summary>
/// <param name="BatchNumber">Latest continuously persisted batch number.</param>
/// <param name="LastBlock">Last L2 block covered by that batch.</param>
/// <param name="PostStateRoot">Validated post-state root used by the next batch.</param>
/// <remarks>See doc.md §7.2, §7.5, and §15.1.</remarks>
public sealed record SealedBatchCheckpoint(
    ulong BatchNumber,
    ulong LastBlock,
    UInt256 PostStateRoot);

/// <summary>
/// Durable hand-off used by the batch plugin to persist a sealed batch before advancing its
/// pre-state root.
/// </summary>
/// <remarks>See doc.md §7.2, §7.5, and §15.1.</remarks>
public interface ISealedBatchSink
{
    /// <summary>
    /// Return the authenticated state root preceding batch 1. Legacy profiles default to zero;
    /// production ZK sinks override this with their committed genesis snapshot root.
    /// </summary>
    ValueTask<UInt256> GetInitialStateRootAsync(
        CancellationToken cancellationToken = default)
        => new(UInt256.Zero);

    /// <summary>
    /// Execute, publish, and atomically persist the batch, returning the validated post-state root.
    /// </summary>
    ValueTask<UInt256> PersistAsync(
        SealedBatch batch,
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Recover the latest checkpoint after validating that committed artifacts form one
    /// continuous batch, block, and state-root chain. Production settlement may refresh
    /// L1 lifecycle (funded RPC) before reading durable artifacts.
    /// </summary>
    ValueTask<SealedBatchCheckpoint?> GetLatestCheckpointAsync(
        CancellationToken cancellationToken = default);

    /// <summary>
    /// Latest contiguous durable checkpoint from local artifacts only — used by
    /// <c>L2BatchPlugin.WithSealedBatchSink</c> to restore the batcher tip offline without
    /// L1 lifecycle refresh. Default falls through to <see cref="GetLatestCheckpointAsync"/>
    /// for in-memory sinks; production settlement overrides to skip funded RPC.
    /// </summary>
    ValueTask<SealedBatchCheckpoint?> GetLatestDurableCheckpointAsync(
        CancellationToken cancellationToken = default)
        => GetLatestCheckpointAsync(cancellationToken);

    /// <summary>
    /// Return forced-inclusion nonces already tracked by durable artifacts.
    /// </summary>
    ValueTask<IReadOnlyCollection<ulong>> GetTrackedForcedInclusionNoncesAsync(
        uint chainId,
        CancellationToken cancellationToken = default);
}

