        var serializerTimes = new List<double>();
        
        for (var i = 0; i < MESSAGES_PER_SECOND; i++)
        {
            var batch = CreateCommitmentFixture(10);
            var data = BatchSerializer.Encode(batch);
            
            // Pad to expected network message size if needed
