[TestClass]
public class UT_BatchSerializer
{
    private static UInt256 H(char c) => UInt256.Parse("0x" + new string(c, 64));

    private static L2BatchCommitment Sample(byte[]? proof = null) => new()
    {
        ChainId = 0xCAFEBABE,
        BatchNumber = 0xDEAD_BEEF_F00D_BABEUL,
