        System.Buffers.Binary.BinaryPrimitives.WriteUInt64LittleEndian(bytes.AsSpan(20, 8), ulong.MaxValue - 1);
        var error = Assert.ThrowsExactly<InvalidDataException>(() => BatchSerializer.DecodePublicInputs(bytes));
