    internal static ProofWitnessArtifactV1 SampleArtifact(ulong batchNumber = 257)
    {
        var payload = SamplePayload(batchNumber);
        var executionResult = new BatchExecutionResult
        {
            PostStateRoot = H(0x31),
            TxRoot = H(0x32),
            ReceiptRoot = H(0x33),
            WithdrawalRoot = H(0x34),
            L2ToL1MessageRoot = H(0x35),
            L2ToL2MessageRoot = H(0x36),
            GasConsumed = 12_345,
        };
        var daReceipt = new DAReceipt
        {
            Layer = DAMode.NeoFS,
            Commitment = ExecutionPayloadSerializer.ComputeCommitment(payload),
            Pointer = new byte[] { 0xa1, 0xa2, 0xa3 },
            Kind = DAReceiptKind.NeoFSObject,
            Evidence = new byte[] { 0xa4, 0xa5 },
        };
        var publicInputs = new PublicInputs
        {
            ChainId = payload.ChainId,
            BatchNumber = payload.BatchNumber,
            FirstBlock = payload.FirstBlock,
            LastBlock = payload.LastBlock,
            PreStateRoot = payload.PreStateRoot,
            PostStateRoot = executionResult.PostStateRoot,
            TxRoot = executionResult.TxRoot,
            ReceiptRoot = executionResult.ReceiptRoot,
            WithdrawalRoot = executionResult.WithdrawalRoot,
            L2ToL1MessageRoot = executionResult.L2ToL1MessageRoot,
            L2ToL2MessageRoot = executionResult.L2ToL2MessageRoot,
            L1MessageHash = StateRootCalculator.HashL1Messages(payload.L1Messages),
            DACommitment = daReceipt.Commitment,
            BlockContextHash = StateRootCalculator.HashBlockContext(payload.BlockContext),
        };
        return ProofWitnessArtifactV1.Create(
            ProofType.Zk,
            WitnessProofSystem.Sp1,
            H(0x41),
            H(0x42),
            true,
            payload.ChainId,
            payload.BatchNumber,
            payload.FirstBlock,
            payload.LastBlock,
            payload,
            new byte[] { 0xb1, 0xb2, 0xb3, 0xb4 },
            executionResult,
            new byte[] { 0xc1, 0xc2 },
            daReceipt,
            publicInputs);
    }

    internal static ExecutionPayloadV1 SamplePayload(ulong batchNumber = 257)
    {
        const uint chainId = 0x1020_3040;
        var unhashedMessage = new CrossChainMessage
        {
            SourceChainId = 0,
            TargetChainId = chainId,
            Nonce = 9,
            Sender = H160(0x11),
            Receiver = H160(0x22),
            MessageType = MessageType.Deposit,
            Payload = new byte[] { 0xd1, 0xd2, 0xd3 },
            MessageHash = UInt256.Zero,
        };
        var message = unhashedMessage with
        {
            MessageHash = MessageHasher.HashMessage(unhashedMessage),
        };
        return new ExecutionPayloadV1
        {
            ChainId = chainId,
            BatchNumber = batchNumber,
            FirstBlock = 100,
            LastBlock = 102,
            PreStateRoot = H(0x10),
            BlockContext = new BatchBlockContext
            {
                L1FinalizedHeight = 88,
                FirstBlockTimestamp = 1_700_000_000,
                LastBlockTimestamp = 1_700_000_012,
                SequencerCommitteeHash = H(0x20),
                Network = 860_833_102,
            },
            L1Messages = [message],
            Transactions =
            [
                new byte[] { 0x01, 0x02 },
                new byte[] { 0x03, 0x04, 0x05 },
            ],
        };
    }

    internal static UInt256 H(byte value)
        => new(Enumerable.Repeat(value, UInt256.Length).ToArray());

    private static UInt160 H160(byte value)
        => new(Enumerable.Repeat(value, UInt160.Length).ToArray());

    private static byte[] Mutate(byte[] source, int index, byte value)
    {
        var mutated = source.ToArray();
        mutated[index] = value;
        return mutated;
    }

    private static void AssertDecodeFails(byte[] data)
        => Assert.ThrowsExactly<InvalidDataException>(
            () => ExecutionPayloadSerializer.Decode(data));

    private static void AssertArtifactDecodeFails(byte[] data)
        => Assert.ThrowsExactly<InvalidDataException>(
            () => ProofWitnessArtifactSerializer.Decode(data));
}

using Neo.Cryptography;
using Neo.L2.State;

namespace Neo.L2.Batch.UnitTests;

[TestClass]
public sealed class UT_Sp1NativeExecutionOutputSerializer
{
    [TestMethod]
    public void RustGoldenFixture_DecodesAndReencodesByteIdentically()
    {
        var bytes = FixtureBytes("native_execution_output_v1.hex");
        var output = Sp1NativeExecutionOutputSerializer.Decode(bytes);

        CollectionAssert.AreEqual(
            bytes,
            Sp1NativeExecutionOutputSerializer.Encode(output));
        Assert.AreEqual(
            ExecutionSemanticIds.Sp1StatefulNeoVmV1,
            output.ExecutionSemanticId);
    }

    [TestMethod]
    public void RustGoldenFixture_BindsExactRequestEffectsAndPublicInputs()
    {
        var artifact = ProofWitnessArtifactSerializer.Decode(
            FixtureBytes("stateful_batch_v1.hex"));
        var output = Sp1NativeExecutionOutputSerializer.Decode(
            FixtureBytes("native_execution_output_v1.hex"));
        var payloadBytes = ExecutionPayloadSerializer.Encode(artifact.ExecutionPayload);

        Assert.AreEqual(
            new UInt256(Crypto.Hash256(payloadBytes)),
            output.RequestPayloadHash);
        Assert.AreEqual(
            new UInt256(Crypto.Hash256(artifact.StateWitness.Span)),
            output.RequestStateWitnessHash);
        Assert.AreEqual(artifact.ExecutionResult, output.ExecutionResult);
        CollectionAssert.AreEqual(artifact.Effects.ToArray(), output.Effects.ToArray());
        Assert.AreEqual(
            StateRootCalculator.HashPublicInputs(artifact.PublicInputs),
            output.PublicInputHash);
        var postState = StateWitnessV1Serializer.Decode(output.PostStateWitness.Span);
        Assert.AreEqual(
            output.ExecutionResult.PostStateRoot,
            KeyedStateMerkleTree.ComputeRoot(postState.Entries.Select(static entry =>
                (entry.Key.ToArray(), entry.Value.ToArray()))));
    }

    [TestMethod]
    public void Decode_RejectsContentTamperingAndTruncation()
    {
        var bytes = FixtureBytes("native_execution_output_v1.hex");
        var tampered = bytes.ToArray();
        tampered[128] ^= 1;

        Assert.ThrowsExactly<InvalidDataException>(() =>
            Sp1NativeExecutionOutputSerializer.Decode(tampered));
        Assert.ThrowsExactly<InvalidDataException>(() =>
            Sp1NativeExecutionOutputSerializer.Decode(bytes.AsSpan(0, bytes.Length - 1)));
    }

    [TestMethod]
    public void Encode_RejectsWrongSemanticAndPostStateRoot()
    {
        var output = Sp1NativeExecutionOutputSerializer.Decode(
            FixtureBytes("native_execution_output_v1.hex"));

        Assert.ThrowsExactly<ArgumentException>(() =>
            Sp1NativeExecutionOutputSerializer.Encode(output with
            {
                ExecutionSemanticId = ExecutionSemanticIds.ReferenceNoOpV1,
            }));
        Assert.ThrowsExactly<ArgumentException>(() =>
            Sp1NativeExecutionOutputSerializer.Encode(output with
            {
                ExecutionResult = output.ExecutionResult with
                {
                    PostStateRoot = UInt256.Zero,
                },
            }));
    }

    private static byte[] FixtureBytes(string fileName)
    {
        var path = Path.Combine(AppContext.BaseDirectory, "Fixtures", fileName);
        return Convert.FromHexString(string.Concat(
            File.ReadAllText(path).Where(static value => !char.IsWhiteSpace(value))));
    }
}

using Neo.L2.State;

namespace Neo.L2.Batch.UnitTests;

[TestClass]
public class UT_StateWitnessV1Serializer
{
    [TestMethod]
    public void RustGoldenFixture_DecodesAndReencodesByteIdentically()
    {
        var artifact = GoldenArtifact();
        var witness = StateWitnessV1Serializer.Decode(artifact.StateWitness.Span);

        CollectionAssert.AreEqual(
            artifact.StateWitness.ToArray(),
            StateWitnessV1Serializer.Encode(witness));
        Assert.AreEqual(2, witness.Entries.Count);
        Assert.AreEqual(1, witness.Contracts.Count);
        Assert.AreEqual(0xff, witness.Entries[1].Key.Span[0]);
        Assert.AreEqual(
            artifact.ExecutionPayload.PreStateRoot,
            KeyedStateMerkleTree.ComputeRoot(
                witness.Entries.Select(static entry =>
                    (entry.Key.ToArray(), entry.Value.ToArray()))));
    }

    [TestMethod]
    public void ContractBinding_MatchesRustGoldenBytes()
    {
        var witness = StateWitnessV1Serializer.Decode(GoldenArtifact().StateWitness.Span);
        var contract = witness.Contracts.Single();
        var binding = witness.Entries.Single(entry =>
            entry.Key.Span.SequenceEqual(
                StateWitnessV1Serializer.ContractBindingKey(contract.Hash)));

        CollectionAssert.AreEqual(
            Convert.FromHexString(
                "f55c786591ed202461901fbbd0d482b9369edbbb2b84d78aafd5f8c16a16c2c9"),
            StateWitnessV1Serializer.ContractBindingHash(contract).GetSpan().ToArray());
        CollectionAssert.AreEqual(
            binding.Value.ToArray(),
            StateWitnessV1Serializer.ContractBindingHash(contract).GetSpan().ToArray());
    }

    [TestMethod]
    public void Encode_RejectsTamperedBindingOrderAndProtocolConfig()
    {
        var witness = StateWitnessV1Serializer.Decode(GoldenArtifact().StateWitness.Span);
        var tamperedEntries = witness.Entries
            .Select(static entry => entry with
            {
                Key = entry.Key.ToArray(),
                Value = entry.Value.ToArray(),
            })
            .ToArray();
        tamperedEntries[1] = tamperedEntries[1] with { Value = new byte[32] };
        Assert.ThrowsExactly<ArgumentException>(() =>
            StateWitnessV1Serializer.Encode(witness with { Entries = tamperedEntries }));
        Assert.ThrowsExactly<ArgumentException>(() =>
            StateWitnessV1Serializer.Encode(witness with
            {
                Entries = witness.Entries.Reverse().ToArray(),
            }));
        Assert.ThrowsExactly<ArgumentException>(() =>
            StateWitnessV1Serializer.Encode(witness with
            {
                ProtocolConfig = witness.ProtocolConfig with { ExecFeeFactor = 31 },
            }));
    }

    [TestMethod]
    public void Decode_RejectsTruncationTrailingBytesAndBindingTampering()
    {
        var bytes = GoldenArtifact().StateWitness.ToArray();
        Assert.ThrowsExactly<InvalidDataException>(() =>
            StateWitnessV1Serializer.Decode(bytes.AsSpan(0, bytes.Length - 1)));
        Assert.ThrowsExactly<InvalidDataException>(() =>
            StateWitnessV1Serializer.Decode([.. bytes, 0x00]));

        var tampered = bytes.ToArray();
        tampered[99] ^= 0x01;
        Assert.ThrowsExactly<InvalidDataException>(() =>
            StateWitnessV1Serializer.Decode(tampered));
    }

    [TestMethod]
    public void ValueSemantics_CompareMemoryByContent()
    {
        var witness = StateWitnessV1Serializer.Decode(GoldenArtifact().StateWitness.Span);
        var clone = witness with
        {
            Entries = witness.Entries.Select(static entry => entry with
            {
                Key = entry.Key.ToArray(),
                Value = entry.Value.ToArray(),
            }).ToArray(),
            Contracts = witness.Contracts.Select(static contract => contract with
            {
                Hash = new UInt160(contract.Hash.GetSpan()),
                Script = contract.Script.ToArray(),
                Manifest = contract.Manifest.ToArray(),
            }).ToArray(),
        };

        Assert.AreEqual(witness, clone);
        Assert.AreEqual(witness.GetHashCode(), clone.GetHashCode());
    }

    private static ProofWitnessArtifactV1 GoldenArtifact()
    {
        var path = Path.Combine(
            AppContext.BaseDirectory, "Fixtures", "stateful_batch_v1.hex");
        var bytes = Convert.FromHexString(string.Concat(
            File.ReadAllText(path).Where(static value => !char.IsWhiteSpace(value))));
        return ProofWitnessArtifactSerializer.Decode(bytes);
    }
